//! A constructor for every workshop value, generated by `build.rs` from the
//! value table in [`ow_workshop_data`].
//!
//! Each function takes the value's arguments in workshop order. Arguments that
//! are constants (a hero, a button, a rounding mode) take the data crate's
//! enum; the rest take anything that converts into a [`Value`].
//!
//! ```
//! use ow_workshop::values::{event_player, has_spawned};
//!
//! assert_eq!(has_spawned(event_player()).to_string(), "Has Spawned(Event Player)");
//! ```

#![allow(clippy::needless_pass_by_value, clippy::too_many_arguments)]

use crate::{CompareOp, Global, PlayerVar, Value, ValueId, data};

include!(concat!(env!("OUT_DIR"), "/values.rs"));
